CREATE OR REPLACE FUNCTION platform_private.guard_manual_cq_write_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE cid uuid; lid uuid; p public.programacao_producao%ROWTYPE; org uuid;
BEGIN
 lid:=CASE WHEN TG_OP='DELETE' THEN OLD.lote_id ELSE NEW.lote_id END;
 SELECT pp.* INTO p FROM public.programacao_producao pp JOIN public.lotes l ON l.programacao_id=pp.id WHERE l.id=lid;
 IF p.ordem_servico_id IS NOT NULL OR p.id IS NULL OR (TG_OP='UPDATE' AND EXISTS(SELECT 1 FROM public.lotes l JOIN public.programacao_producao pp ON pp.id=l.programacao_id WHERE l.id=OLD.lote_id AND pp.ordem_servico_id IS NOT NULL)) THEN
  org:=platform_private.h15_actor_organization();
  IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'CQ_MANUAL_REQUIRES_REVIEWED_RPC' USING ERRCODE='42501'; END IF;
  IF auth.uid() IS NULL OR org IS NULL OR public.technical_actor_ready(auth.uid()) IS NOT TRUE
   OR p.organization_id IS DISTINCT FROM org OR NEW.organization_id IS DISTINCT FROM org
   OR p.ordem_servico_onfarm_id IS NOT NULL OR NEW.resultado IS NULL
   OR NEW.responsavel IS DISTINCT FROM 'DADOS FICTICIOS SEM VALOR COMERCIAL'
   OR NEW.responsavel_id IS DISTINCT FROM (SELECT id FROM public.profiles WHERE user_id=auth.uid() AND ativo AND organization_id=org)
   OR NOT EXISTS(SELECT 1 FROM public.lotes l JOIN public.ordens_servico o ON o.id=p.ordem_servico_id JOIN public.clientes c ON c.id=o.cliente_id
     WHERE l.id=lid AND l.organization_id=org AND o.organization_id=org AND c.organization_id=org AND o.status::text='em_cq' AND l.status::text='aguardando_cq')
   OR NOT EXISTS(SELECT 1 FROM platform_private.authz_tickets WHERE txid=txid_current() AND scope='manual_cq_insert_v1' AND target=NEW.id)
   THEN RAISE EXCEPTION 'CQ_MANUAL_REQUIRES_REVIEWED_RPC' USING ERRCODE='42501'; END IF;
 END IF;
 RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END $function$

CREATE OR REPLACE FUNCTION public.guard_tenant_organization_id()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE v_org uuid;
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN NEW;
  END IF;
  v_org := public.h15_actor_organization();
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'tenant_context_required' USING ERRCODE = '42501';
  END IF;
  IF TG_OP = 'INSERT' AND NEW.organization_id IS NULL THEN
    NEW.organization_id := v_org;
  END IF;
  IF NEW.organization_id IS DISTINCT FROM v_org THEN
    RAISE EXCEPTION 'tenant_scope_violation' USING ERRCODE = '42501';
  END IF;
  IF TG_OP = 'UPDATE' AND NEW.organization_id IS DISTINCT FROM OLD.organization_id THEN
    RAISE EXCEPTION 'tenant_immutable' USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_cq_aprovado_avanca_os()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_prog_id uuid;
  v_os_onfarm_id uuid;
  v_os_id uuid;
BEGIN
  IF EXISTS(SELECT 1 FROM public.lotes l JOIN public.programacao_producao p ON p.id=l.programacao_id WHERE l.id=NEW.lote_id AND p.ordem_servico_id IS NOT NULL) THEN RETURN NEW; END IF;
  IF NEW.resultado::text <> 'aprovado' THEN
    RETURN NEW;
  END IF;

  SELECT programacao_id INTO v_prog_id FROM public.lotes WHERE id = NEW.lote_id;
  IF v_prog_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT ordem_servico_onfarm_id, ordem_servico_id
    INTO v_os_onfarm_id, v_os_id
    FROM public.programacao_producao
    WHERE id = v_prog_id;

  -- Mirror status on programacao and lote
  UPDATE public.programacao_producao SET status = 'aprovado' WHERE id = v_prog_id;
  UPDATE public.lotes SET status = 'aprovado' WHERE id = NEW.lote_id;

  -- Advance OS On-Farm if it is at em_producao or em_cq
  IF v_os_onfarm_id IS NOT NULL THEN
    UPDATE public.ordens_servico_onfarm
      SET status = 'envase'
      WHERE id = v_os_onfarm_id
        AND status::text IN ('em_producao','em_cq');
  END IF;

  -- Advance legacy OS if it is at em_producao or em_cq
  IF v_os_id IS NOT NULL THEN
    UPDATE public.ordens_servico
      SET status = 'envase'
      WHERE id = v_os_id
        AND status::text IN ('em_producao','em_cq');
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_cq_autoria_servidor()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_profile uuid;
BEGIN
  -- Sem excecao por GUC: autoria e imutabilidade valem em todas as chamadas.
  IF TG_OP = 'INSERT' THEN
    IF v_uid IS NOT NULL THEN
      SELECT id INTO v_profile FROM public.profiles WHERE user_id = v_uid LIMIT 1;
      IF v_profile IS NOT NULL THEN
        IF NEW.responsavel_id IS NOT NULL AND NEW.responsavel_id IS DISTINCT FROM v_profile THEN
          RAISE EXCEPTION 'CQ_AUTORIA_FORJADA: responsavel_id informado (%) difere do perfil do usuario autenticado.', NEW.responsavel_id
            USING ERRCODE = 'check_violation';
        END IF;
        NEW.responsavel_id := v_profile;
      ELSIF NEW.responsavel_id IS NOT NULL THEN
        RAISE EXCEPTION 'CQ_AUTORIA_FORJADA: usuario autenticado sem perfil nao pode informar responsavel_id.'
          USING ERRCODE = 'check_violation';
      END IF;
    END IF;
    RETURN NEW;
  END IF;

  IF NEW.responsavel_id IS DISTINCT FROM OLD.responsavel_id THEN
    RAISE EXCEPTION 'CQ_AUTORIA_IMUTAVEL: responsavel_id da analise % nao pode ser alterado.', OLD.id
      USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.created_at IS DISTINCT FROM OLD.created_at
     OR NEW.seq IS DISTINCT FROM OLD.seq
     OR NEW.lote_id IS DISTINCT FROM OLD.lote_id THEN
    RAISE EXCEPTION 'CQ_TRILHA_IMUTAVEL: created_at/seq/lote_id da analise % nao podem ser alterados.', OLD.id
      USING ERRCODE = 'check_violation';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public._saas_trg_require_feature()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_key text := TG_ARGV[0];
BEGIN
  IF v_uid IS NULL THEN
    RETURN COALESCE(NEW, OLD);
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM public.profiles p
    JOIN public.organizations o ON o.id = p.organization_id AND o.ativo IS TRUE
    WHERE p.user_id = v_uid AND p.ativo IS TRUE AND p.organization_id IS NOT NULL
  ) THEN
    RAISE EXCEPTION 'saas_context_unavailable: usuário ativo e empresa são obrigatórios'
      USING ERRCODE = '42501';
  END IF;
  IF NOT public._saas_user_has_feature(v_uid, v_key) THEN
    RAISE EXCEPTION 'saas_feature_not_entitled: funcionalidade não contratada ou assinatura indisponível'
      USING ERRCODE = '42501';
  END IF;
  RETURN COALESCE(NEW, OLD);
END;
$function$

CREATE OR REPLACE FUNCTION public.tg_entrega_termos_immutability()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.status <> 'rascunho' THEN
      RAISE EXCEPTION 'termo_imutavel: documento % nao pode ser excluido', OLD.id
        USING ERRCODE = 'raise_exception';
    END IF;
    RETURN OLD;
  END IF;

  IF OLD.status IN ('assinado','cancelado','substituido') THEN
    IF NEW.snapshot IS DISTINCT FROM OLD.snapshot
       OR NEW.snapshot_hash IS DISTINCT FROM OLD.snapshot_hash
       OR NEW.versao IS DISTINCT FROM OLD.versao
       OR NEW.template_versao IS DISTINCT FROM OLD.template_versao
       OR NEW.entrega_id IS DISTINCT FROM OLD.entrega_id
       OR NEW.recebedor_nome IS DISTINCT FROM OLD.recebedor_nome
       OR NEW.recebedor_documento IS DISTINCT FROM OLD.recebedor_documento
       OR NEW.assinatura_hash IS DISTINCT FROM OLD.assinatura_hash
       OR NEW.assinado_em IS DISTINCT FROM OLD.assinado_em
       OR NEW.assinado_por IS DISTINCT FROM OLD.assinado_por
       OR NEW.cobertura IS DISTINCT FROM OLD.cobertura THEN
      RAISE EXCEPTION 'termo_imutavel: documento assinado nao pode ser alterado'
        USING ERRCODE = 'raise_exception';
    END IF;
    -- PDF só pode ser gravado uma vez por versão
    IF OLD.pdf_path IS NOT NULL AND NEW.pdf_path IS DISTINCT FROM OLD.pdf_path THEN
      RAISE EXCEPTION 'termo_pdf_imutavel: ja existe PDF ativo para esta versao'
        USING ERRCODE = 'raise_exception';
    END IF;
    IF OLD.status <> 'assinado' AND NEW.status <> OLD.status THEN
      RAISE EXCEPTION 'termo_estado_terminal: transicao % -> % proibida', OLD.status, NEW.status
        USING ERRCODE = 'raise_exception';
    END IF;
  END IF;

  NEW.updated_at := now();
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION platform_private.stock_p1_movement_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$ DECLARE v_org uuid:=public.h15_actor_organization(); v_lote uuid; v_ref uuid;
BEGIN
IF auth.uid() IS NULL OR v_org IS NULL THEN RAISE EXCEPTION 'ESTQ_MOV_TENANT_FORBIDDEN' USING ERRCODE='42501'; END IF;
SELECT e.lote_id INTO v_lote FROM public.estoque_produto e WHERE e.id=NEW.estoque_produto_id;
IF v_lote IS NULL OR NOT platform_private.stock_p1_lote_owned(v_lote) THEN RAISE EXCEPTION 'ESTQ_MOV_TENANT_FORBIDDEN' USING ERRCODE='42501'; END IF;
-- Only a new ledger row may inherit its verified stock's lote, never organization or legacy backfill.
IF NEW.lote_id IS NULL THEN NEW.lote_id:=v_lote; END IF;
IF NEW.lote_id IS DISTINCT FROM v_lote THEN RAISE EXCEPTION 'ESTQ_MOV_REFERENCE_FORBIDDEN' USING ERRCODE='42501'; END IF;
IF NEW.cliente_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.clientes c WHERE c.id=NEW.cliente_id AND c.organization_id=v_org) THEN RAISE EXCEPTION 'ESTQ_MOV_REFERENCE_FORBIDDEN' USING ERRCODE='42501'; END IF;
IF NEW.os_id IS NOT NULL THEN
 IF NEW.os_tipo IN ('manual','b2b') THEN SELECT o.organization_id INTO v_ref FROM public.ordens_servico o WHERE o.id=NEW.os_id;
 ELSIF NEW.os_tipo IN ('onfarm','on_farm') THEN SELECT c.organization_id INTO v_ref FROM public.ordens_servico_onfarm o JOIN public.clientes c ON c.id=o.cliente_id WHERE o.id=NEW.os_id;
 ELSE RAISE EXCEPTION 'ESTQ_MOV_REFERENCE_FORBIDDEN' USING ERRCODE='42501'; END IF;
 IF v_ref IS DISTINCT FROM v_org THEN RAISE EXCEPTION 'ESTQ_MOV_REFERENCE_FORBIDDEN' USING ERRCODE='42501'; END IF;
END IF;
IF NEW.movimentacao_origem_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.estoque_movimentacoes m WHERE m.id=NEW.movimentacao_origem_id AND m.estoque_produto_id=NEW.estoque_produto_id AND m.lote_id=NEW.lote_id) THEN RAISE EXCEPTION 'ESTQ_MOV_REFERENCE_FORBIDDEN' USING ERRCODE='42501'; END IF;
IF NEW.referencia_id IS NOT NULL THEN
 IF NEW.referencia_tipo='entrega' THEN
  IF NOT EXISTS(SELECT 1 FROM public.entregas e WHERE e.id=NEW.referencia_id AND e.organization_id=v_org AND (e.lote_id IS NULL OR e.lote_id=NEW.lote_id) AND (NEW.cliente_id IS NULL OR e.cliente_id=NEW.cliente_id)) THEN RAISE EXCEPTION 'ESTQ_MOV_REFERENCE_FORBIDDEN' USING ERRCODE='42501'; END IF;
 ELSIF NEW.referencia_tipo IN ('estoque','estoque_produto') THEN
  IF NEW.referencia_id IS DISTINCT FROM NEW.estoque_produto_id THEN RAISE EXCEPTION 'ESTQ_MOV_REFERENCE_FORBIDDEN' USING ERRCODE='42501'; END IF;
 ELSIF NEW.referencia_tipo IN ('os','ordem_servico') THEN
  IF NEW.os_id IS NULL OR NEW.referencia_id IS DISTINCT FROM NEW.os_id THEN RAISE EXCEPTION 'ESTQ_MOV_REFERENCE_FORBIDDEN' USING ERRCODE='42501'; END IF;
 ELSE RAISE EXCEPTION 'ESTQ_MOV_REFERENCE_UNSUPPORTED' USING ERRCODE='42501'; END IF;
END IF;
RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.fn_entrega_evidencia_estado_editavel_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE v_id uuid; v_status text; v_comp_status text;
BEGIN
 IF TG_OP='UPDATE' AND NEW.entrega_id IS DISTINCT FROM OLD.entrega_id THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Não é permitido transferir evidências entre entregas.';
 END IF;
 IF TG_OP='DELETE' THEN v_id:=OLD.entrega_id; ELSE v_id:=NEW.entrega_id; END IF;
 SELECT e.status,e.comprovante_status INTO v_status,v_comp_status
 FROM public.entregas e WHERE e.id=v_id FOR SHARE;
 IF NOT FOUND THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Entrega não encontrada ou sem acesso.';
 END IF;
 IF v_status='cancelada' OR v_comp_status IN ('confirmado','dispensado') THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='As evidências desta entrega estão encerradas e não podem ser alteradas.';
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_entrega_assinatura_exigir_imagem_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN
 IF NEW.assinatura_tipo='digital_tela' AND NEW.assinatura_digital_png_path IS NULL THEN
  RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='A assinatura digital exige uma imagem armazenada.';
 END IF;
 IF NEW.assinatura_digital_png_path IS NOT NULL AND NOT EXISTS (
  SELECT 1 FROM storage.objects o
  WHERE o.bucket_id='entrega-documentos' AND o.name=NEW.assinatura_digital_png_path
 ) THEN
  RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Imagem da assinatura não encontrada ou sem acesso no armazenamento.';
 END IF;
 RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_entrega_comprovante_exigir_arquivo_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN
  IF NEW.arquivo_path IS NULL THEN
    IF NEW.assinatura_tipo = 'fisica_anexada' THEN
      RAISE EXCEPTION USING ERRCODE = '23514',
        MESSAGE = 'O comprovante físico exige um arquivo anexado.';
    END IF;
    RETURN NEW;
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM storage.objects AS o
    WHERE o.bucket_id = 'entrega-documentos'
      AND o.name = NEW.arquivo_path
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'Arquivo do comprovante não encontrado ou sem acesso no armazenamento.';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_entrega_comprovante_preservar_encerrado_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
 v_operacionais text[]:=ARRAY['updated_at','metadata','qr_code_path','qr_code_generated_at','validation_public_enabled','validation_expires_at','validation_url'];
 v_campo text;
BEGIN
 IF TG_OP='DELETE' THEN
  IF OLD.status='confirmado' OR OLD.metadata ? 'comprovante_snapshot_v1' THEN
   RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Comprovante encerrado não pode ser excluído.';
  END IF;
  RETURN OLD;
 END IF;
 IF OLD.status='confirmado' AND
   (to_jsonb(NEW)-v_operacionais) IS DISTINCT FROM (to_jsonb(OLD)-v_operacionais) THEN
  RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Dados do comprovante confirmado não podem ser alterados.';
 END IF;
 IF OLD.metadata ? 'comprovante_snapshot_v1' THEN
  IF NEW.id IS DISTINCT FROM OLD.id OR NEW.entrega_id IS DISTINCT FROM OLD.entrega_id THEN
   RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Vínculo do comprovante congelado não pode ser alterado.';
  END IF;
  FOREACH v_campo IN ARRAY ARRAY['comprovante_snapshot_v1','comprovante_snapshot_hash','comprovante_numero'] LOOP
   IF NEW.metadata->v_campo IS DISTINCT FROM OLD.metadata->v_campo THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Conteúdo do comprovante congelado não pode ser alterado.';
   END IF;
  END LOOP;
 END IF;
 RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_tenant_organization_id()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE v_org uuid;
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN NEW;
  END IF;
  v_org := public.h15_actor_organization();
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'tenant_context_required' USING ERRCODE = '42501';
  END IF;
  IF TG_OP = 'INSERT' AND NEW.organization_id IS NULL THEN
    NEW.organization_id := v_org;
  END IF;
  IF NEW.organization_id IS DISTINCT FROM v_org THEN
    RAISE EXCEPTION 'tenant_scope_violation' USING ERRCODE = '42501';
  END IF;
  IF TG_OP = 'UPDATE' AND NEW.organization_id IS DISTINCT FROM OLD.organization_id THEN
    RAISE EXCEPTION 'tenant_immutable' USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_entrega_marcar_cancelamento()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
 IF NEW.status::text='cancelada' AND (TG_OP='INSERT' OR OLD.status::text IS DISTINCT FROM 'cancelada') THEN
  UPDATE platform_private.delivery_context_20261030 SET consumed=true
   WHERE txid=pg_catalog.txid_current() AND actor=auth.uid() AND organization_id=NEW.organization_id
    AND action='cancel' AND target=NEW.id AND consumed=false;
  IF NOT FOUND THEN RAISE EXCEPTION 'ENTREGA_CANCELAMENTO_EXIGE_RPC' USING ERRCODE='42501'; END IF;
  NEW.cancelada_em:=COALESCE(NEW.cancelada_em,pg_catalog.now()); NEW.cancelada_por:=auth.uid();
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.trg_entrega_sync_partner_order_fn()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_partner_order_id uuid;
  v_total int; v_delivered int;
BEGIN
  SELECT os.partner_order_id INTO v_partner_order_id
    FROM public.ordens_servico os WHERE os.id = COALESCE(NEW.ordem_servico_id, OLD.ordem_servico_id);
  IF v_partner_order_id IS NULL THEN RETURN NEW; END IF;

  SELECT COUNT(*), COUNT(*) FILTER (WHERE e.status = 'entregue')
    INTO v_total, v_delivered
    FROM public.entregas e
    JOIN public.ordens_servico os ON os.id = e.ordem_servico_id
   WHERE os.partner_order_id = v_partner_order_id;

  IF v_total > 0 AND v_delivered = v_total THEN
    UPDATE public.partner_orders SET status = 'entregue', updated_at = now()
      WHERE id = v_partner_order_id AND status <> 'entregue';
    UPDATE public.production_planning SET status = 'entregue', updated_at = now()
      WHERE partner_order_id = v_partner_order_id;
    INSERT INTO public.production_timeline_events (partner_order_id, event_type, meta)
    VALUES (v_partner_order_id, 'entrega_realizada', jsonb_build_object('total', v_total));
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.tg_recalc_planning_from_entrega()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_po uuid;
BEGIN
  IF NEW.ordem_servico_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT l.partner_order_id INTO v_po
    FROM public.production_order_link l
   WHERE l.ordem_servico_id = NEW.ordem_servico_id
   LIMIT 1;

  IF v_po IS NOT NULL THEN
    PERFORM public.recalc_partner_order_production(v_po);
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_sync_entrega_financial_status()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  -- bloqueia troca de receivable_id já vinculado
  IF TG_OP = 'UPDATE'
     AND OLD.receivable_id IS NOT NULL
     AND NEW.receivable_id IS DISTINCT FROM OLD.receivable_id THEN
    RAISE EXCEPTION 'Esta entrega já possui faturamento gerado e não pode ser alterada.'
      USING ERRCODE = 'check_violation';
  END IF;

  -- vinculou receivable agora => BILLED
  IF (TG_OP = 'INSERT' AND NEW.receivable_id IS NOT NULL)
     OR (TG_OP = 'UPDATE' AND OLD.receivable_id IS NULL AND NEW.receivable_id IS NOT NULL) THEN
    NEW.financial_status := 'BILLED';
    NEW.billing_generated_at := COALESCE(NEW.billing_generated_at, now());
    NEW.billing_generated_by := COALESCE(NEW.billing_generated_by, auth.uid());
  END IF;

  -- entrega cancelada
  IF NEW.status::text = 'cancelada' THEN
    NEW.financial_status := 'CANCELED';
  END IF;

  -- valida NOT_BILLABLE
  IF NEW.financial_status = 'NOT_BILLABLE'
     AND (NEW.not_billable_reason IS NULL OR length(trim(NEW.not_billable_reason)) = 0) THEN
    RAISE EXCEPTION 'Informe o motivo para marcar a entrega como sem cobrança.'
      USING ERRCODE = 'check_violation';
  END IF;

  -- default quando não definido
  IF NEW.financial_status IS NULL THEN
    NEW.financial_status := 'PENDING_BILLING';
  END IF;

  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.fn_validate_entrega_confirmacao()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_anexos int;
BEGIN
  IF NEW.status::text = 'entregue'
     AND (TG_OP = 'INSERT' OR OLD.status::text IS DISTINCT FROM 'entregue') THEN

    IF TG_OP = 'UPDATE' AND OLD.status::text = 'cancelada' THEN
      RAISE EXCEPTION 'Não é possível confirmar uma entrega cancelada.'
        USING ERRCODE = 'check_violation';
    END IF;

    IF COALESCE(TRIM(NEW.recebido_por_nome), '') = '' THEN
      RAISE EXCEPTION 'Informe o nome de quem recebeu a entrega.'
        USING ERRCODE = 'check_violation';
    END IF;

    IF NEW.confirmado_por IS NULL THEN
      RAISE EXCEPTION 'A entrega precisa ser confirmada por um usuário autenticado.'
        USING ERRCODE = 'check_violation';
    END IF;

    IF NEW.entregue_em IS NULL THEN
      NEW.entregue_em := now();
    END IF;

    IF NEW.comprovante_entrega_obrigatorio THEN
      SELECT count(*) INTO v_anexos
        FROM public.entrega_documentos
        WHERE entrega_id = NEW.id;
      IF v_anexos = 0 THEN
        RAISE EXCEPTION 'É obrigatório anexar pelo menos um comprovante para confirmar esta entrega.'
          USING ERRCODE = 'check_violation';
      END IF;
    END IF;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_validate_entrega_estoque()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_estoque_id uuid;
  v_qtd_fisica_disponivel numeric;
  v_qtd_reservada_os numeric;
  v_qtd_ja_entregue_lote_os numeric;
  v_lote_codigo text;
BEGIN
  -- Se a entrega já está sendo criada/atualizada como cancelada, não validar saldo
  IF NEW.status::text = 'cancelada' THEN
    RETURN NEW;
  END IF;

  v_estoque_id := NEW.estoque_produto_id;

  IF v_estoque_id IS NULL THEN
    RAISE EXCEPTION 'ID do estoque não informado na entrega.' USING ERRCODE = 'check_violation';
  END IF;

  SELECT 
    ep.quantidade, 
    ep.quantidade_reservada,
    l.codigo_lote
  INTO 
    v_qtd_fisica_disponivel, 
    v_qtd_reservada_os,
    v_lote_codigo
  FROM public.estoque_produto ep
  JOIN public.lotes l ON l.id = ep.lote_id
  WHERE ep.id = v_estoque_id;

  -- Acumula somente entregas válidas (ignora canceladas)
  SELECT COALESCE(SUM(quantidade_entregue), 0)
  INTO v_qtd_ja_entregue_lote_os
  FROM public.entregas
  WHERE estoque_produto_id = v_estoque_id 
    AND ordem_servico_id = NEW.ordem_servico_id
    AND id <> NEW.id
    AND status::text <> 'cancelada';

  IF NEW.quantidade_entregue > v_qtd_fisica_disponivel THEN
    RAISE EXCEPTION 'Saldo físico insuficiente no lote %. Disponível: %, Solicitado: %.',
      v_lote_codigo, v_qtd_fisica_disponivel, NEW.quantidade_entregue
      USING ERRCODE = 'check_violation';
  END IF;

  IF (v_qtd_ja_entregue_lote_os + NEW.quantidade_entregue) > v_qtd_reservada_os THEN
    RAISE EXCEPTION 'Quantidade excede o saldo reservado para esta Ordem de Serviço no lote %. Reservado total: %, Já entregue: %, Saldo restante: %.',
      v_lote_codigo, v_qtd_reservada_os, v_qtd_ja_entregue_lote_os, (v_qtd_reservada_os - v_qtd_ja_entregue_lote_os)
      USING ERRCODE = 'check_violation';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION platform_private.delivery_mutation_guard_20261030()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE c platform_private.delivery_context_20261030%ROWTYPE; v_org uuid;
 v_proof text[]:=ARRAY['comprovante_status','assinatura_tipo','recebedor_nome','recebedor_documento','recebedor_cargo','recebedor_telefone','comprovante_anexado_em','comprovante_anexado_por','assinatura_digital_capturada_em','assinatura_digital_capturada_por','comprovante_id','formulario_gerado_em','formulario_gerado_por','validation_token','validation_hash','updated_at'];
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'DELIVERY_MUTATION_CLOSED' USING ERRCODE='42501'; END IF;
 SELECT * INTO c FROM platform_private.delivery_context_20261030
 WHERE txid=pg_catalog.txid_current() AND actor=auth.uid();
 IF NOT FOUND THEN RAISE EXCEPTION 'DELIVERY_MUTATION_CLOSED' USING ERRCODE='42501'; END IF;
 IF c.action='proof' THEN
  v_org:=platform_private.delivery_proof_actor_20261030();
  IF TG_OP='UPDATE' AND c.mutation='proof' AND c.organization_id=v_org AND NEW.id=c.target AND OLD.id=c.target
  AND OLD.organization_id=v_org AND NEW.organization_id=v_org
  AND OLD.partner_order_id IS NULL AND NEW.partner_order_id IS NULL
  AND OLD.ordem_servico_onfarm_id IS NULL AND NEW.ordem_servico_onfarm_id IS NULL
  AND NEW.status=OLD.status AND NEW.receivable_id IS NOT DISTINCT FROM OLD.receivable_id
  AND (pg_catalog.to_jsonb(NEW)-v_proof) IS NOT DISTINCT FROM (pg_catalog.to_jsonb(OLD)-v_proof) THEN
   UPDATE platform_private.delivery_context_20261030 SET mutation='done' WHERE txid=c.txid;
   RETURN NEW;
  END IF;
  RAISE EXCEPTION 'DELIVERY_MUTATION_CLOSED' USING ERRCODE='42501';
 END IF;
 v_org:=platform_private.delivery_actor_20261030(c.action);
 IF c.organization_id IS DISTINCT FROM v_org OR NEW.organization_id IS DISTINCT FROM v_org
 OR NEW.partner_order_id IS NOT NULL OR NEW.receivable_id IS NOT NULL OR NEW.ordem_servico_onfarm_id IS NOT NULL
 THEN RAISE EXCEPTION 'DELIVERY_MUTATION_CLOSED' USING ERRCODE='42501'; END IF;
 IF c.action='group' AND TG_OP='INSERT' AND c.mutation='create' AND c.delivery IS NULL
 AND NEW.ordem_servico_id=c.target AND NEW.estoque_produto_id=c.item AND NEW.status::text='separado' THEN
  UPDATE platform_private.delivery_context_20261030 SET delivery=NEW.id,mutation='decorate' WHERE txid=c.txid;
 ELSIF c.action='group' AND TG_OP='UPDATE' AND c.mutation='decorate' AND NEW.id=c.delivery
 AND OLD.id=c.delivery AND NEW.ordem_servico_id=c.target AND NEW.estoque_produto_id=c.item
 AND NEW.organization_id=OLD.organization_id AND NEW.status=OLD.status THEN
  UPDATE platform_private.delivery_context_20261030 SET mutation='done' WHERE txid=c.txid;
 ELSIF c.action='cancel' AND TG_OP='UPDATE' AND c.mutation='cancel' AND NEW.id=c.target AND OLD.id=c.target
 AND OLD.organization_id=v_org AND NEW.status::text='cancelada' AND NEW.financial_status='CANCELED'
 AND (pg_catalog.to_jsonb(NEW)-ARRAY['status','motivo_cancelamento','updated_at','cancelada_em','cancelada_por','financial_status'])
 IS NOT DISTINCT FROM (pg_catalog.to_jsonb(OLD)-ARRAY['status','motivo_cancelamento','updated_at','cancelada_em','cancelada_por','financial_status']) THEN
  UPDATE platform_private.delivery_context_20261030 SET mutation='done' WHERE txid=c.txid;
 ELSE RAISE EXCEPTION 'DELIVERY_MUTATION_CLOSED' USING ERRCODE='42501'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION platform_private.stock_p1_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
 v_org uuid := public.h15_actor_organization();
 v_ref uuid;
 v_lote public.lotes%ROWTYPE;
BEGIN
 IF auth.uid() IS NULL OR v_org IS NULL THEN
  RAISE EXCEPTION 'ESTQ_TENANT_FORBIDDEN' USING ERRCODE='42501';
 END IF;
 IF TG_OP IN ('UPDATE','DELETE') AND NOT platform_private.stock_p1_lote_owned(OLD.lote_id) THEN
  RAISE EXCEPTION 'ESTQ_TENANT_FORBIDDEN' USING ERRCODE='42501';
 END IF;
 IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
 IF NOT platform_private.stock_p1_lote_owned(NEW.lote_id) THEN
  RAISE EXCEPTION 'ESTQ_TENANT_FORBIDDEN' USING ERRCODE='42501';
 END IF;
 SELECT * INTO v_lote FROM public.lotes WHERE id=NEW.lote_id;
 -- Explicit lote ownership is required; parent references never assign ownership.
 IF v_lote.programacao_id IS NOT NULL AND NOT EXISTS (
  SELECT 1 FROM public.programacao_producao p
   WHERE p.id=v_lote.programacao_id AND p.organization_id=v_org
 ) THEN RAISE EXCEPTION 'ESTQ_REFERENCE_FORBIDDEN' USING ERRCODE='42501'; END IF;
 IF NEW.envase_id IS NOT NULL AND NOT EXISTS (
  SELECT 1 FROM public.envase e WHERE e.id=NEW.envase_id
   AND e.lote_id=NEW.lote_id AND e.organization_id=v_org
 ) THEN RAISE EXCEPTION 'ESTQ_REFERENCE_FORBIDDEN' USING ERRCODE='42501'; END IF;
 IF NEW.reservado_para_cliente_id IS NOT NULL AND NOT EXISTS (
  SELECT 1 FROM public.clientes c WHERE c.id=NEW.reservado_para_cliente_id AND c.organization_id=v_org
 ) THEN RAISE EXCEPTION 'ESTQ_REFERENCE_FORBIDDEN' USING ERRCODE='42501'; END IF;
 IF NEW.reservado_para_partner_id IS NOT NULL AND NOT coalesce(public.b2b_phase1_partner_visible(NEW.reservado_para_partner_id,false),false) THEN
  RAISE EXCEPTION 'ESTQ_REFERENCE_FORBIDDEN' USING ERRCODE='42501';
 END IF;
 IF NEW.reservado_para_partner_order_id IS NOT NULL AND NOT EXISTS (
  SELECT 1 FROM public.partner_orders o WHERE o.id=NEW.reservado_para_partner_order_id
    AND o.partner_id=NEW.reservado_para_partner_id
    AND public.b2b_phase1_order_visible(o.id)
 ) THEN RAISE EXCEPTION 'ESTQ_REFERENCE_FORBIDDEN' USING ERRCODE='42501'; END IF;
 IF NEW.reservado_para_os_id IS NOT NULL THEN
  IF NEW.reservado_para_os_tipo IN ('onfarm','on_farm') THEN
   SELECT c.organization_id INTO v_ref FROM public.ordens_servico_onfarm o
    JOIN public.clientes c ON c.id=o.cliente_id WHERE o.id=NEW.reservado_para_os_id;
  ELSIF NEW.reservado_para_os_tipo IN ('manual','b2b') THEN
   SELECT o.organization_id INTO v_ref FROM public.ordens_servico o WHERE o.id=NEW.reservado_para_os_id;
  ELSE
   RAISE EXCEPTION 'ESTQ_REFERENCE_FORBIDDEN' USING ERRCODE='42501';
  END IF;
  IF v_ref IS DISTINCT FROM v_org THEN
   RAISE EXCEPTION 'ESTQ_REFERENCE_FORBIDDEN' USING ERRCODE='42501';
  END IF;
 END IF;
 RETURN NEW;
END;
$function$

