CREATE OR REPLACE FUNCTION public._saas_trg_require_feature()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_key text := TG_ARGV[0];
BEGIN
  IF v_uid IS NULL THEN
    RETURN COALESCE(NEW, OLD);
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM public.profiles p
    JOIN public.organizations o ON o.id = p.organization_id AND o.ativo IS TRUE
    WHERE p.user_id = v_uid AND p.ativo IS TRUE AND p.organization_id IS NOT NULL
  ) THEN
    RAISE EXCEPTION 'saas_context_unavailable: usuário ativo e empresa são obrigatórios'
      USING ERRCODE = '42501';
  END IF;
  IF NOT public._saas_user_has_feature(v_uid, v_key) THEN
    RAISE EXCEPTION 'saas_feature_not_entitled: funcionalidade não contratada ou assinatura indisponível'
      USING ERRCODE = '42501';
  END IF;
  RETURN COALESCE(NEW, OLD);
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_sync_os_classica_downstream()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_prog_id uuid;
  v_lote_id uuid;
BEGIN
  IF (OLD.status IS NOT DISTINCT FROM NEW.status) THEN
    RETURN NEW;
  END IF;

  SELECT id INTO v_prog_id FROM public.programacao_producao
   WHERE ordem_servico_id = NEW.id ORDER BY created_at DESC LIMIT 1;

  IF v_prog_id IS NULL
     AND NEW.status::text IN ('aprovada','programada','em_producao','em_cq','envase','pronto_entrega','entregue','finalizada')
     AND (NEW.produto_id IS NOT NULL OR NEW.microrganismo_id IS NOT NULL) THEN
    INSERT INTO public.programacao_producao
      (produto_id, microrganismo_id, volume_necessario, data_programada, status, ordem_servico_id)
    VALUES
      (NEW.produto_id, NEW.microrganismo_id, NEW.volume_total_ml,
       COALESCE(NEW.data_programada, CURRENT_DATE), 'aguardando', NEW.id)
    RETURNING id INTO v_prog_id;
  END IF;

  IF v_prog_id IS NOT NULL THEN
    SELECT id INTO v_lote_id FROM public.lotes
      WHERE programacao_id = v_prog_id ORDER BY created_at DESC LIMIT 1;
  END IF;

  CASE NEW.status::text
    WHEN 'aprovada' THEN
      IF v_prog_id IS NOT NULL THEN
        UPDATE public.programacao_producao SET status = 'aguardando' WHERE id = v_prog_id;
      END IF;
    WHEN 'programada' THEN
      IF v_prog_id IS NOT NULL THEN
        UPDATE public.programacao_producao
           SET status = 'aguardando',
               data_programada = COALESCE(NEW.data_programada, data_programada, CURRENT_DATE)
         WHERE id = v_prog_id;
      END IF;
    WHEN 'em_producao' THEN
      IF v_prog_id IS NOT NULL THEN
        UPDATE public.programacao_producao SET status = 'em_producao' WHERE id = v_prog_id;
      END IF;
      IF v_lote_id IS NULL AND (NEW.produto_id IS NOT NULL OR NEW.microrganismo_id IS NOT NULL) THEN
        INSERT INTO public.lotes (codigo_lote, produto_id, microrganismo_id, programacao_id, status, volume_produzido, data_producao)
        VALUES (public.gerar_codigo_lote(), NEW.produto_id, NEW.microrganismo_id, v_prog_id,
                'em_producao', NEW.volume_total_ml, CURRENT_DATE);
      END IF;
    WHEN 'em_cq' THEN
      IF v_prog_id IS NOT NULL THEN
        UPDATE public.programacao_producao SET status = 'aguardando_cq' WHERE id = v_prog_id;
      END IF;
      IF v_lote_id IS NOT NULL THEN
        UPDATE public.lotes SET status = 'aguardando_cq' WHERE id = v_lote_id;
      END IF;
    WHEN 'envase' THEN
      IF v_prog_id IS NOT NULL THEN
        UPDATE public.programacao_producao SET status = 'aprovado' WHERE id = v_prog_id;
      END IF;
    ELSE
      NULL;
  END CASE;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public._sync_planning_from_os()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_partner_order_id uuid;
  v_planning_id uuid;
  v_total int;
  v_done int;
  v_in_prod int;
BEGIN
  v_partner_order_id := COALESCE(NEW.partner_order_id, OLD.partner_order_id);
  IF v_partner_order_id IS NULL THEN RETURN NEW; END IF;

  SELECT id INTO v_planning_id FROM public.production_planning WHERE partner_order_id = v_partner_order_id;
  IF v_planning_id IS NULL THEN RETURN NEW; END IF;

  SELECT COUNT(*),
         COUNT(*) FILTER (WHERE status IN ('finalizada','entregue','pronto_entrega')),
         COUNT(*) FILTER (WHERE status IN ('em_producao','em_cq','envase','programada'))
    INTO v_total, v_done, v_in_prod
  FROM public.ordens_servico WHERE partner_order_id = v_partner_order_id;

  IF v_total = 0 THEN RETURN NEW; END IF;

  IF v_done = v_total THEN
    UPDATE public.production_planning SET status='produzido', updated_at=now()
      WHERE id=v_planning_id AND status <> 'produzido';
  ELSIF v_in_prod > 0 THEN
    UPDATE public.production_planning SET status='em_producao', updated_at=now()
      WHERE id=v_planning_id AND status NOT IN ('em_producao','produzido','entregue');
  END IF;

  RETURN NEW;
END
$function$

CREATE OR REPLACE FUNCTION private.guard_os_separate_approval()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_origin text; v_org uuid;
BEGIN
 IF TG_OP='INSERT' THEN
 -- Criação normal exclusivamente aberta, inclusive pelo serviço/DEFINER.
 -- NULL e qualquer estado avançado não podem saltar a aprovação humana.
 -- Sem whitelist service_role, flags GUC ou reparo de históricos.
 IF NEW.status::text IS DISTINCT FROM 'aberta' THEN RAISE EXCEPTION 'OS_APPROVAL_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 RETURN NEW;
 END IF;
 IF NEW.status::text IS DISTINCT FROM 'aprovada' THEN RETURN NEW; END IF;
 v_origin:=CASE TG_TABLE_NAME WHEN 'ordens_servico' THEN 'manual' WHEN 'ordens_servico_onfarm' THEN 'onfarm' END;
 IF TG_WHEN='BEFORE' THEN
 -- Um único UPDATE não pode substituir a identidade/referências e aprovar o estado anterior.
 IF (to_jsonb(NEW)-ARRAY['status','updated_at']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['status','updated_at']) THEN RAISE EXCEPTION 'OS_APPROVAL_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 v_org:=private.assert_os_approval_scope(OLD.id,v_origin);
 RETURN NEW;
 END IF;
 IF OLD.status::text='aberta' THEN
 v_org:=private.assert_os_approval_scope(NEW.id,v_origin);
 INSERT INTO public.laboratorio_esteira_eventos(os_id,origem_os,programacao_id,etapa_anterior,etapa_nova,acao,usuario_id,observacao)
 SELECT NEW.id,v_origin,pp.id,'aberta','aprovada','aprovar_os',auth.uid(),jsonb_build_object(
 'organization_id',v_org,'before',jsonb_build_object('status',OLD.status,'volume',OLD.volume_total_ml,'data_os',to_jsonb(OLD)->'data_programada'),
 'after',jsonb_build_object('status',NEW.status,'volume',NEW.volume_total_ml,'data_os',to_jsonb(NEW)->'data_programada'),
 'programacao',jsonb_build_object('id',pp.id,'status',pp.status,'data',pp.data_programada,'volume',pp.volume_necessario),
 'actor',auth.uid(),'at',clock_timestamp(),'manufacturing_started',false,'commercial_completed',false)::text
 FROM public.programacao_producao pp WHERE pp.ordem_servico_id=NEW.id OR pp.ordem_servico_onfarm_id=NEW.id;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION platform_private.guard_manual_cq_parent_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE ticket text; org uuid; linked boolean;
BEGIN
 IF TG_TABLE_NAME='ordens_servico' THEN
  linked:=EXISTS(SELECT 1 FROM public.programacao_producao p JOIN public.lotes l ON l.programacao_id=p.id WHERE p.ordem_servico_id=OLD.id AND l.organization_id IS NOT NULL);
  IF linked AND OLD.status::text='em_cq' AND NEW.status::text='envase'
   AND (to_jsonb(NEW)-'status'-'updated_at') IS NOT DISTINCT FROM (to_jsonb(OLD)-'status'-'updated_at')
   AND EXISTS(SELECT 1 FROM platform_private.authz_tickets WHERE txid=txid_current() AND scope='manual_envase_transition_v1' AND target=OLD.id)
   AND EXISTS(SELECT 1 FROM public.programacao_producao p JOIN public.lotes l ON l.programacao_id=p.id
    WHERE p.ordem_servico_id=OLD.id AND l.status::text='aprovado' AND l.organization_id=OLD.organization_id)
  THEN RETURN NEW; END IF;
  IF linked AND OLD.status::text='em_cq' AND
   (to_jsonb(NEW)-'updated_at') IS DISTINCT FROM (to_jsonb(OLD)-'updated_at') THEN
   RAISE EXCEPTION 'CQ_MANUAL_PARENT_REQUIRES_REVIEWED_RPC' USING ERRCODE='42501';
  END IF;
  IF linked AND (OLD.status::text='em_cq' OR NEW.status::text='em_cq') AND NEW.status IS DISTINCT FROM OLD.status THEN
   IF OLD.status::text IS DISTINCT FROM 'programada' OR NEW.status::text IS DISTINCT FROM 'em_cq'
    OR (to_jsonb(NEW)-'status'-'updated_at') IS DISTINCT FROM (to_jsonb(OLD)-'status'-'updated_at')
    OR NOT EXISTS(SELECT 1 FROM platform_private.authz_tickets WHERE txid=txid_current() AND scope='manual_cq_send_v1' AND target=OLD.id)
   THEN RAISE EXCEPTION 'CQ_MANUAL_PARENT_REQUIRES_REVIEWED_RPC' USING ERRCODE='42501'; END IF;
  END IF;
 ELSE
  linked:=OLD.ordem_servico_id IS NOT NULL AND EXISTS(SELECT 1 FROM public.lotes l WHERE l.programacao_id=OLD.id AND l.organization_id IS NOT NULL);
  IF linked AND (NEW.id IS DISTINCT FROM OLD.id OR NEW.ordem_servico_id IS DISTINCT FROM OLD.ordem_servico_id
   OR NEW.ordem_servico_onfarm_id IS DISTINCT FROM OLD.ordem_servico_onfarm_id
   OR NEW.organization_id IS DISTINCT FROM OLD.organization_id
   OR NEW.produto_id IS DISTINCT FROM OLD.produto_id OR NEW.microrganismo_id IS DISTINCT FROM OLD.microrganismo_id) THEN
   RAISE EXCEPTION 'CQ_MANUAL_PARENT_REQUIRES_REVIEWED_RPC' USING ERRCODE='42501';
  END IF;
  IF linked AND (OLD.status::text IN ('aguardando_cq','aprovado') OR NEW.status::text IN ('aguardando_cq','aprovado')) AND NEW IS DISTINCT FROM OLD THEN
   ticket:=CASE WHEN OLD.status::text='aguardando' AND NEW.status::text='aguardando_cq' THEN 'manual_cq_send_v1'
     WHEN OLD.status::text='aguardando_cq' AND NEW.status::text='aprovado' THEN 'manual_cq_aprovado_v1' END;
   IF ticket IS NULL OR (to_jsonb(NEW)-'status'-'updated_at') IS DISTINCT FROM (to_jsonb(OLD)-'status'-'updated_at')
    OR NOT EXISTS(SELECT 1 FROM platform_private.authz_tickets WHERE txid=txid_current() AND scope=ticket AND target=OLD.id)
   THEN RAISE EXCEPTION 'CQ_MANUAL_PARENT_REQUIRES_REVIEWED_RPC' USING ERRCODE='42501'; END IF;
  END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.guard_tenant_organization_id()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE v_org uuid;
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN NEW;
  END IF;
  v_org := public.h15_actor_organization();
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'tenant_context_required' USING ERRCODE = '42501';
  END IF;
  IF TG_OP = 'INSERT' AND NEW.organization_id IS NULL THEN
    NEW.organization_id := v_org;
  END IF;
  IF NEW.organization_id IS DISTINCT FROM v_org THEN
    RAISE EXCEPTION 'tenant_scope_violation' USING ERRCODE = '42501';
  END IF;
  IF TG_OP = 'UPDATE' AND NEW.organization_id IS DISTINCT FROM OLD.organization_id THEN
    RAISE EXCEPTION 'tenant_immutable' USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_notify_lab_on_programacao()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$ DECLARE org uuid; prod text; cli text; BEGIN
 IF NEW.status::text<>'aguardando' THEN RETURN NEW; END IF;
 org:=platform_private.notification_source_org('programacao_producao',NEW.id);
 IF org IS NULL THEN RETURN NEW; END IF;
 SELECT nome INTO prod FROM public.produtos WHERE id=NEW.produto_id;
 SELECT c.nome INTO cli FROM public.ordens_servico o JOIN public.clientes c ON c.id=o.cliente_id AND c.organization_id=org WHERE o.id=NEW.ordem_servico_id;
 INSERT INTO public.notificacoes_operacionais(usuario_id,tipo,titulo,mensagem,link,source_type,source_id)
 SELECT DISTINCT ur.user_id,'nova_demanda_producao','Nova demanda de produção',coalesce(prod,'Bioinsumo')||coalesce(' · '||cli,'')||coalesce(' · '||round(NEW.volume_necessario/1000.0,1)::text||' L',''),'/pcp?coluna=aguardando','programacao_producao',NEW.id
 FROM public.user_roles ur WHERE ur.role IN ('producao','administrador','gestor') AND platform_private.notification_user_ok(ur.user_id,org);
 RETURN NEW; END $function$

CREATE OR REPLACE FUNCTION public.validate_responsavel_producao()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid;
  v_ok boolean;
BEGIN
  IF NEW.responsavel_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT user_id INTO v_user_id
  FROM public.profiles
  WHERE id = NEW.responsavel_id;

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Responsável inválido: perfil não encontrado'
      USING ERRCODE = 'check_violation';
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM public.user_roles
    WHERE user_id = v_user_id
      AND role::text IN ('administrador','gestor','operador_onfarm','producao')
  ) INTO v_ok;

  IF NOT v_ok THEN
    RAISE EXCEPTION 'Responsável inválido: perfil sem permissão para produção do laboratório'
      USING ERRCODE = 'check_violation';
  END IF;

  RETURN NEW;
END;
$function$
